import org.apache.commons.lang3.reflect.MethodUtils;
import java.lang.reflect.Method;

public class Dbg {
    interface AmbiguousA {
        String process(Number n);
    }
    interface AmbiguousB {
        default String process(final Number n) {
            return "B:" + n;
        }
    }
    static class AmbiguousImpl implements AmbiguousA, AmbiguousB {
        @Override
        public String process(final Number n) {
            return "impl:" + n;
        }
    }
    public static void main(String[] args) throws Exception {
        Method m = MethodUtils.getMatchingMethod(AmbiguousImpl.class, "process", Integer.class);
        System.out.println(m);
    }
}
EOF
